```st
FUNCTION_BLOCK FB
VAR_INPUT
    runRequest      : BOOL;
    pressure        : REAL;
    pressureValid   : BOOL;
    fuelFlow        : REAL;
    steamFlow       : REAL;
    outletCmd       : INT;
    outletFeedback  : INT;
    resetBtn        : BOOL;
END_VAR

VAR_OUTPUT
    tripLatched        : BOOL;
    fuelPermit         : BOOL;
    currentCauseMask   : WORD;
    latchedCauseMask   : WORD;
    diagnosticActive   : BOOL;
END_VAR

VAR
    prevResetBtn        : BOOL;
    tripLatchedInternal : BOOL;
    latchedCauseMaskInt : WORD;
    valveStuckCounter   : INT;
    resetRising         : BOOL;
    bit0                : BOOL;
    bit1                : BOOL;
    bit2                : BOOL;
    bit3                : BOOL;
END_VAR

(* Detect rising edge of reset button *)
resetRising := resetBtn AND NOT prevResetBtn;

(* Valve‑stuck detection – count consecutive scans meeting the criteria *)
IF runRequest AND pressureValid AND (pressure >= 4500.0) AND (outletCmd >= 50) AND (outletFeedback <= 10) THEN
    valveStuckCounter := valveStuckCounter + 1;
ELSE
    valveStuckCounter := 0;
END_IF

(* Compute cause‑bit mask *)
IF NOT runRequest THEN
    currentCauseMask := 0;
    bit0 := FALSE;
    bit1 := FALSE;
    bit2 := FALSE;
    bit3 := FALSE;
ELSE
    bit0 := NOT pressureValid;
    bit1 := (valveStuckCounter >= 3);
    bit2 := (pressureValid AND (pressure >= 4500.0) AND (fuelFlow >= 4.0) AND (steamFlow <= 10.0));
    bit3 := (pressureValid AND (pressure >= 4500.0) AND NOT bit0 AND NOT bit1 AND NOT bit2);
    currentCauseMask := 0;
    IF bit0 THEN currentCauseMask := currentCauseMask OR WORD#1; END_IF;
    IF bit1 THEN currentCauseMask := currentCauseMask OR WORD#2; END_IF;
    IF bit2 THEN currentCauseMask := currentCauseMask OR WORD#4; END_IF;
    IF bit3 THEN currentCauseMask := currentCauseMask OR WORD#8; END_IF;
END_IF

(* Trip‑latch logic *)
IF resetRising AND NOT runRequest AND pressureValid AND (pressure <= 4200.0) THEN
    tripLatchedInternal := FALSE;
ELSIF runRequest AND ((pressureValid AND (pressure >= 4500.0)) OR (NOT pressureValid)) THEN
    tripLatchedInternal := TRUE;
END_IF

(* Fuel permit *)
fuelPermit := runRequest AND NOT tripLatchedInternal;

(* Accumulate latched cause mask while the latch is active, clear on reset *)
IF tripLatchedInternal THEN
    latchedCauseMaskInt := latchedCauseMaskInt OR currentCauseMask;
ELSE
    latchedCauseMaskInt := 0;
END_IF

(* Diagnostic active flag *)
diagnosticActive := (currentCauseMask <> 0);

(* Assign outputs *)
tripLatched   := tripLatchedInternal;
latchedCauseMask := latchedCauseMaskInt;

(* Update button history for edge detection *)
prevResetBtn := resetBtn;

END_FUNCTION_BLOCK
```

